def shift_left(row):
    hs=set(j for j in range(5) if row[j])
    stays=set()
    for j in range(5):
        if j in hs:
            if j==0 or ((j-1) in hs and (j-1) in stays):
                stays.add(j)
    new=set()
    for j in hs:
        new.add(j-1 if j not in stays else j)
    return [1 if j in new else 0 for j in range(5)]

